//! Integration tests for maram

use assert_cmd::Command;
use predicates::prelude::*;
use std::fs::{self, File};
use std::io::Write;
use tempfile::TempDir;

/// Helper to create a test directory structure
fn create_test_tree() -> TempDir {
    let temp_dir = TempDir::new().unwrap();
    let root = temp_dir.path();

    // Create directory structure
    fs::create_dir(root.join("src")).unwrap();
    fs::create_dir(root.join("tests")).unwrap();
    fs::create_dir(root.join("docs")).unwrap();
    fs::create_dir(root.join(".git")).unwrap();

    // Create files with content
    let mut file = File::create(root.join("README.md")).unwrap();
    writeln!(file, "# Test Project\n\nThis is a test.").unwrap();

    let mut file = File::create(root.join("Cargo.toml")).unwrap();
    writeln!(file, "[package]\nname = \"test\"\nversion = \"0.1.0\"").unwrap();

    let mut file = File::create(root.join("src/main.rs")).unwrap();
    writeln!(file, "fn main() {{\n    println!(\"Hello, world!\");\n}}").unwrap();

    let mut file = File::create(root.join("src/lib.rs")).unwrap();
    writeln!(file, "pub fn add(a: i32, b: i32) -> i32 {{\n    a + b\n}}").unwrap();

    let mut file = File::create(root.join("tests/test.rs")).unwrap();
    writeln!(
        file,
        "#[test]\nfn test_add() {{\n    assert_eq!(2 + 2, 4);\n}}"
    )
    .unwrap();

    let mut file = File::create(root.join(".gitignore")).unwrap();
    writeln!(file, "target/\n*.log").unwrap();

    temp_dir
}

#[test]
fn test_basic_tree() {
    let temp_dir = create_test_tree();

    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .assert()
        .success()
        .stdout(predicate::str::contains("README.md"))
        .stdout(predicate::str::contains("Cargo.toml"))
        .stdout(predicate::str::contains("src"));
}

#[test]
fn test_show_hidden() {
    let temp_dir = create_test_tree();

    // Without --all, .git should not be shown
    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .assert()
        .success()
        .stdout(predicate::str::contains(".git").not());

    // With --all, .git should be shown
    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .arg("--all")
        .assert()
        .success()
        .stdout(predicate::str::contains(".git"));
}

#[test]
fn test_max_depth() {
    let temp_dir = create_test_tree();

    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .arg("--depth=1")
        .assert()
        .success()
        .stdout(predicate::str::contains("main.rs").not())
        .stdout(predicate::str::contains("src"));
}

#[test]
fn test_only_dirs() {
    let temp_dir = create_test_tree();

    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .arg("--only-dirs")
        .assert()
        .success()
        .stdout(predicate::str::contains("README.md").not())
        .stdout(predicate::str::contains("src"));
}

#[test]
fn test_json_output() {
    let temp_dir = create_test_tree();

    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .arg("--output=json")
        .assert()
        .success()
        .stdout(predicate::str::contains("\"name\""))
        .stdout(predicate::str::contains("\"size\""))
        .stdout(predicate::str::contains("\"is_dir\""));
}

#[test]
fn test_sort_by_size() {
    let temp_dir = create_test_tree();

    // Create files with different sizes
    let mut file = File::create(temp_dir.path().join("small.txt")).unwrap();
    write!(file, "a").unwrap();

    let mut file = File::create(temp_dir.path().join("large.txt")).unwrap();
    write!(file, "{}", "x".repeat(1000)).unwrap();

    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .arg("--sort=size")
        .arg("--reverse")
        .assert()
        .success();
}

#[test]
fn test_search() {
    let temp_dir = create_test_tree();

    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .arg("--search=main")
        .assert()
        .success()
        .stdout(predicate::str::contains("main.rs"))
        .stdout(predicate::str::contains("lib.rs").not());
}

#[test]
fn test_gitignore() {
    let temp_dir = create_test_tree();

    // Create a file that should be ignored
    File::create(temp_dir.path().join("test.log")).unwrap();

    let mut cmd = Command::cargo_bin("maram").unwrap();
    cmd.arg(temp_dir.path())
        .arg("--gitignore")
        .assert()
        .success()
        .stdout(predicate::str::contains("test.log").not());
}

use maram::{generate, MaramOptions, OutputFormat};

fn main() -> maram::Result<()> {
    let options = MaramOptions { output: OutputFormat::Tree, ..Default::default() };
    let out = generate(".", &options)?;
    print!("{}", out);
    Ok(())
}

use maram::{generate, MaramOptions, OutputFormat};

fn main() -> maram::Result<()> {
    let options = MaramOptions { output: OutputFormat::Json, ..Default::default() };
    let out = generate(".", &options)?;
    println!("{}", out);
    Ok(())
}

use maram::{generate, FilterOptions, MaramOptions, OutputFormat};

fn main() -> maram::Result<()> {
    let filter = FilterOptions { max_depth: Some(2), ..Default::default() };
    let options = MaramOptions { output: OutputFormat::Tree, filter, ..Default::default() };
    let out = generate(".", &options)?;
    println!("{}", out);
    Ok(())
}

use maram::{generate_to_writer, MaramOptions, OutputFormat};
use std::fs::File;

fn main() -> maram::Result<()> {
    let options = MaramOptions { output: OutputFormat::Plain, ..Default::default() };
    let mut file = File::create("tree.txt")?;
    generate_to_writer(".", &options, &mut file)?;
    println!("Wrote tree to tree.txt");
    Ok(())
}

//! Benchmarks for line counting

use criterion::{criterion_group, criterion_main, Criterion};
use maram::stats::count_lines;
use std::io::Write;
use tempfile::NamedTempFile;
use std::hint::black_box;

fn create_file_with_lines(lines: usize) -> NamedTempFile {
    let mut file = NamedTempFile::new().unwrap();
    for i in 0..lines {
        writeln!(file, "This is line number {}", i).unwrap();
    }
    file.flush().unwrap();
    file
}

fn benchmark_small_file(c: &mut Criterion) {
    let file = create_file_with_lines(100);

    c.bench_function("count_lines_100", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 10_000_000).unwrap();
        });
    });
}

fn benchmark_medium_file(c: &mut Criterion) {
    let file = create_file_with_lines(10_000);

    c.bench_function("count_lines_10k", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 10_000_000).unwrap();
        });
    });
}

fn benchmark_large_file(c: &mut Criterion) {
    let file = create_file_with_lines(100_000);

    c.bench_function("count_lines_100k", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 100_000_000).unwrap();
        });
    });
}

fn benchmark_binary_detection(c: &mut Criterion) {
    // Create a binary file
    let mut file = NamedTempFile::new().unwrap();
    file.write_all(&[0, 1, 2, 3, 255, 254, 253]).unwrap();
    file.flush().unwrap();

    c.bench_function("binary_detection", |b| {
        b.iter(|| {
            let _ = count_lines(black_box(file.path()), 10_000_000).unwrap();
        });
    });
}

criterion_group!(
    benches,
    benchmark_small_file,
    benchmark_medium_file,
    benchmark_large_file,
    benchmark_binary_detection
);
criterion_main!(benches);
